    node.ir_type == "Access"
    result := find_open_bind_in_value(node.left)
} else = result {
    node.ir_type == "Sum"
    result := find_open_bind_in_value(node.left)
} else = result {
    node.ir_type == "Sum"
    result := find_open_bind_in_value(node.right)
}

